import{_ as i,o as a,c as n,ai as t}from"./chunks/framework.BxxKhjs3.js";const e="/pub-blog/assets/image-20241224094003606.BdrWfQ9T.png",l="/pub-blog/assets/PixPin_2024-12-24_10-22-23.DfaAnzP6.gif",p="/pub-blog/assets/PixPin_2024-12-24_10-48-50.Cgfopmr0.gif",h="/pub-blog/assets/PixPin_2024-12-24_11-22-25.BwInjtkH.gif",u=JSON.parse('{"title":"小白必看 HarmonyOS Next HMRouter 轻松上手秘籍","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/小白必看 HarmonyOS Next HMRouter 轻松上手秘籍/小白必看 HarmonyOS Next HMRouter 轻松上手秘籍.md","filePath":"鸿蒙开发技巧/小白必看 HarmonyOS Next HMRouter 轻松上手秘籍/小白必看 HarmonyOS Next HMRouter 轻松上手秘籍.md","lastUpdated":1735131334000,"__rawMarkdown":"# 小白必看 HarmonyOS Next HMRouter 轻松上手秘籍\\n\\n## 前言\\n\\nHMRouter 作为 HarmonyOS 的页面跳转场景解决方案，聚焦解决应用内原生页面的跳转逻辑。\\n\\nHMRouter 底层对系统 Navigation 进行封装，集成了 Navigation、NavDestination、NavPathStack 的系统能力，提供了可复用的路由拦截、页面生命周期、自定义转场动画，并且在跳转传参、额外的生命周期、服务型路由方面对系统能力进行了扩展。\\n\\n目的是让开发者在开发过程中无需关注 Navigation、NavDestination 容器组件的相关细节及模板代码，屏蔽跳转时的判断逻辑，降低拦截器、自定义转场动画实现复杂度，更好的进行模块间解耦\\n\\n## 对比\\n\\n目前鸿蒙应用开发中，官方推出的路由方案有两个，分别是[Router](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides-V5/arkts-routing-V5)和[Navigation](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides-V5/arkts-navigation-navigation-V5)。目前官方主要推荐的也是 Navigation。\\n\\n| 业务场景                                      | Navigation                            | Router                                      |\\n| :-------------------------------------------- | :------------------------------------ | :------------------------------------------ |\\n| 一多能力                                      | 支持，Auto 模式自适应单栏跟双栏显示   | 不支持                                      |\\n| 跳转指定页面                                  | pushPath & pushDestination            | pushUrl & pushNameRoute                     |\\n| 跳转 HSP 中页面                               | 支持                                  | 支持                                        |\\n| 跳转 HAR 中页面                               | 支持                                  | 支持                                        |\\n| 跳转传参                                      | 支持                                  | 支持                                        |\\n| 获取指定页面参数                              | 支持                                  | 不支持                                      |\\n| 传参类型                                      | 传参为对象形式                        | 传参为对象形式，对象中暂不支持方法变量      |\\n| 跳转结果回调                                  | 支持                                  | 支持                                        |\\n| 跳转单例页面                                  | 支持                                  | 支持                                        |\\n| 页面返回                                      | 支持                                  | 支持                                        |\\n| 页面返回传参                                  | 支持                                  | 支持                                        |\\n| 返回指定路由                                  | 支持                                  | 支持                                        |\\n| 页面返回弹窗                                  | 支持，通过路由拦截实现                | showAlertBeforeBackPage                     |\\n| 路由替换                                      | replacePath & replacePathByName       | replaceUrl & replaceNameRoute               |\\n| 路由栈清理                                    | clear                                 | clear                                       |\\n| 清理指定路由                                  | removeByIndexes & removeByName        | 不支持                                      |\\n| 转场动画                                      | 支持                                  | 支持                                        |\\n| 自定义转场动画                                | 支持                                  | 支持，动画类型受限                          |\\n| 屏蔽转场动画                                  | 支持全局和单次                        | 支持 设置 pageTransition 方法 duration 为 0 |\\n| geometryTransition 共享元素动画               | 支持（NavDestination 之间共享）       | 不支持                                      |\\n| 页面生命周期监听                              | UIObserver.on(\'navDestinationUpdate\') | UIObserver.on(\'routerPageUpdate\')           |\\n| 获取页面栈对象                                | 支持                                  | 不支持                                      |\\n| 路由拦截                                      | 支持通过 setInterception 做路由拦截   | 不支持                                      |\\n| 路由栈信息查询                                | 支持                                  | getState() & getLength()                    |\\n| 路由栈 move 操作                              | moveToTop & moveIndexToTop            | 不支持                                      |\\n| 沉浸式页面                                    | 支持                                  | 不支持，需通过 window 配置                  |\\n| 设置页面标题栏（titlebar）和工具栏（toolbar） | 支持                                  | 不支持                                      |\\n| 模态嵌套路由                                  | 支持                                  | 不支持                                      |\\n\\n但是原生的 Navigation 缺少了路由拦截、页面生命周期、自定义转场动画，并且在跳转传参、额外的生命周期、服务型路由。\\n\\n因此 HMRouter 便是对此做出了拓展和增强。\\n\\n## 学习目标\\n\\n接下来，将通过这篇文章带领小伙伴上手[HMRouter](https://gitee.com/hadss/hmrouter)的应用。\\n\\n## 工程目录\\n\\n新建完工程后，再新建一个 `Cart` 动态共享包模块\\n\\n1. 工程的目录名称是 study\\n2. 入口模块是 entry\\n3. cart 是 hsp 模块\\n\\n![image-20241224094003606](%E5%B0%8F%E7%99%BD%E5%BF%85%E7%9C%8B%20HarmonyOS%20Next%20HMRouter%20%E8%BD%BB%E6%9D%BE%E4%B8%8A%E6%89%8B%E7%A7%98%E7%B1%8D.assets/image-20241224094003606.png)\\n\\n## 配置环境\\n\\n### 使用 ohpm 安装依赖\\n\\n```\\nohpm install @hadss/hmrouter\\nohpm install @hadss/hmrouter-transitions\\n```\\n\\n### 编译插件配置\\n\\n1. 修改工程的`hvigor/hvigor-config.json`文件，加入路由编译插件\\n\\n   ```json\\n   {\\n     \\"dependencies\\": {\\n       \\"@hadss/hmrouter-plugin\\": \\"^1.0.0-rc.10\\"\\n       // 使用npm仓版本号\\n     }\\n     // ...其他配置\\n   }\\n   ```\\n\\n2. 在使用到 HMRouter 的模块中引入路由编译插件，修改`hvigorfile.ts`\\n\\n   > 我们项目的模块无非是 Hap、Har 和 Hsp。对应你当前的模块是哪种类型，就使用对应的写法\\n\\n   1. **Hap**\\n\\n      ```javascript\\n      // entry/hvigorfile.ts  entry模块的hvigorfile.ts\\n      import { hapTasks } from \\"@ohos/hvigor-ohos-plugin\\";\\n      import { hapPlugin } from \\"@hadss/hmrouter-plugin\\";\\n\\n      export default {\\n        system: hapTasks,\\n        plugins: [hapPlugin()], // 使用HMRouter标签的模块均需要配置，与模块类型保持一致\\n      };\\n      ```\\n\\n   2. **Har**\\n\\n      ```javascript\\n      import { harTasks } from \\"@ohos/hvigor-ohos-plugin\\";\\n      import { harPlugin } from \\"@hadss/hmrouter-plugin\\";\\n\\n      export default {\\n        system: harTasks,\\n        plugins: [harPlugin()], // 使用HMRouter标签的模块均需要配置，与模块类型保持一致\\n      };\\n      ```\\n\\n   3. **Hsp**\\n\\n      ```javascript\\n      import { hspTasks } from \\"@ohos/hvigor-ohos-plugin\\";\\n      import { hspPlugin } from \\"@hadss/hmrouter-plugin\\";\\n\\n      export default {\\n        system: hspTasks,\\n        plugins: [hspPlugin()], // 使用HMRouter标签的模块均需要配置，与模块类型保持一致\\n      };\\n      ```\\n\\n### 初始化路由框架\\n\\n> entry/src/main/ets/entryability/EntryAbility.ets\\n\\n```javascript\\nexport default class EntryAbility extends UIAbility {\\n  onCreate(want: Want, launchParam: AbilityConstant.LaunchParam): void {\\n    HMRouterMgr.init({\\n      context: this.context,\\n    });\\n  }\\n}\\n```\\n\\n### 定义路由入口\\n\\n> entry/src/main/ets/pages/Index.ets\\n\\n当前页面作为整个路由的根容器\\n\\n```typescript\\nimport { HMDefaultGlobalAnimator, HMNavigation } from \\"@hadss/hmrouter\\";\\nimport { AttributeUpdater } from \\"@kit.ArkUI\\";\\n\\nclass MyNavModifier extends AttributeUpdater<NavigationAttribute> {\\n  initializeModifier(instance: NavigationAttribute): void {\\n    // instance.hideNavBar(true);  // 先注释掉  否则看不见结果\\n  }\\n}\\n\\n@Entry\\n@Component\\nexport struct Index {\\n  modifier: MyNavModifier = new MyNavModifier();\\n\\n  build() {\\n    // @Entry中需要再套一层容器组件,Column或者Stack\\n    Column() {\\n      // 使用HMNavigation容器\\n      HMNavigation({\\n        navigationId: \'mainNavigation\', homePageUrl: \'MainPage\',\\n        options: {\\n          standardAnimator: HMDefaultGlobalAnimator.STANDARD_ANIMATOR,\\n          dialogAnimator: HMDefaultGlobalAnimator.DIALOG_ANIMATOR,\\n          modifier: this.modifier\\n        }\\n      }) {\\n        Column({ space: 10 }) {\\n          Button(\\"跳转到 登录页面\\")\\n        }\\n      }\\n    }\\n    .height(\'100%\')\\n    .width(\'100%\')\\n  }\\n}\\n```\\n\\n## 模块内跳转\\n\\n![PixPin_2024-12-24_10-22-23](%E5%B0%8F%E7%99%BD%E5%BF%85%E7%9C%8B%20HarmonyOS%20Next%20HMRouter%20%E8%BD%BB%E6%9D%BE%E4%B8%8A%E6%89%8B%E7%A7%98%E7%B1%8D.assets/PixPin_2024-12-24_10-22-23.gif)\\n\\n我们先演示跳转到当前模块中的某个页面。\\n\\nHMRouter 默认指定了 页面目录 为 `entry/src/main/ets/components`\\n\\n我们在这个里新建一个组件 `entry/src/main/ets/components/LoginPage.ets`\\n\\n```typescript\\nimport { HMRouter } from \\"@hadss/hmrouter\\"\\n\\n@HMRouter({\\n  pageUrl: \'LoginPage\',\\n})\\n@Component\\nexport struct LoginPage {\\n  build() {\\n    Column() {\\n      Button(\'登录页面\')\\n    }\\n    .width(\\"100%\\")\\n    .height(\\"100%\\")\\n    .justifyContent(FlexAlign.Center)\\n  }\\n}\\n```\\n\\n此时，回到首页中，进行点击跳转登录\\n\\n```typescript\\nButton(\\"跳转到 登录页面\\").onClick(() => {\\n  HMRouterMgr.push({ pageUrl: \\"LoginPage\\" });\\n});\\n```\\n\\n## 路由传参\\n\\n### 传递\\n\\n```javascript\\nHMRouterMgr.push({ pageUrl: \\"LoginPage\\", param: { 数据 } });\\n```\\n\\n### 接收\\n\\n```javascript\\nHMRouterMgr.getCurrentParam(HMParamType.all);\\n```\\n\\n## 指定编译目录\\n\\n刚才的登录页面是存放到 components 目录下的，实际开发中，我们可以会通过 **views**来存放**页面**，所以这里来设置下\\n\\n在项目根目录创建路由编译插件配置文件`study/hmrouter_config.json`（可选）\\n\\n```json\\n{\\n  \\"scanDir\\": [\\"src/main/ets/views\\"]\\n}\\n```\\n\\n然后重命名之前的文件夹名字 `entry/src/main/ets/components` 为 `entry/src/main/ets/views`\\n\\n重新编译执行即可\\n\\n## 模块之间跳转\\n\\n刚才的演示是在同一个模块内进行的，现在我们来演示不同模块之间的跳转\\n\\n演示的目标是 entry 模块跳转到 cart 模块\\n\\n### cart 模块配置编译插件\\n\\n> cart 是 hsp\\n>\\n> cart/hvigorfile.ts\\n\\n```javascript\\nimport { hspTasks } from \\"@ohos/hvigor-ohos-plugin\\";\\nimport { hspPlugin } from \\"@hadss/hmrouter-plugin\\";\\n\\nexport default {\\n  system: hspTasks,\\n  plugins: [hspPlugin()], // 使用HMRouter标签的模块均需要配置，与模块类型保持一致\\n};\\n```\\n\\n### 新建购物详情页面\\n\\n> cart/src/main/ets/views/CartDetail.ets\\n\\n```typescript\\nimport { HMRouter } from \\"@hadss/hmrouter\\"\\n\\n@HMRouter({\\n  pageUrl: \'CartDetail\',\\n})\\n@Component\\nexport struct CartDetail {\\n  build() {\\n    Column() {\\n      Button(\'我的是购物车详情页面\')\\n    }\\n    .width(\\"100%\\")\\n    .height(\\"100%\\")\\n    .justifyContent(FlexAlign.Center)\\n  }\\n}\\n```\\n\\n### entry 模块引入 cart 模块\\n\\n> entry/oh-package.json5\\n\\n```json\\n  \\"dependencies\\": {\\n    \\"cart\\": \\"file:../cart\\"\\n  },\\n```\\n\\n### 首页中进行跳转\\n\\n> entry/src/main/ets/pages/Index.ets\\n\\n```javascript\\nButton(\\"跳转到 购物车详情页面\\").onClick(() => {\\n  HMRouterMgr.push({ pageUrl: \\"CartDetail\\" });\\n});\\n```\\n\\n### 效果\\n\\n![PixPin_2024-12-24_10-48-50](%E5%B0%8F%E7%99%BD%E5%BF%85%E7%9C%8B%20HarmonyOS%20Next%20HMRouter%20%E8%BD%BB%E6%9D%BE%E4%B8%8A%E6%89%8B%E7%A7%98%E7%B1%8D.assets/PixPin_2024-12-24_10-48-50.gif)\\n\\n## 跳转动画\\n\\n我们可以在跳转页面的时候来指定跳转动画\\n\\n分类两个步骤\\n\\n1. 定义动画\\n2. 使用动画\\n\\n### 定义动画\\n\\n假设 A 跳转 B, 那么就是 B 使用动画，为了方便使用，可以在 B 页面定义动画\\n\\n我们继续使用上面的例子\\n\\nindex 跳转到 CarDetail ， 所以在 CarDetail 定义动画\\n\\n> cart/src/main/ets/views/CartDetail.ets\\n\\n```javascript\\n@HMAnimator({ animatorName: \\"liveCommentsAnimator\\" })\\nexport class liveCommentsAnimator implements IHMAnimator {\\n  effect(enterHandle: HMAnimatorHandle, exitHandle: HMAnimatorHandle): void {\\n    // 入场动画\\n    enterHandle.start(\\n      (\\n        translateOption: TranslateOption,\\n        scaleOption: ScaleOption,\\n        opacityOption: OpacityOption\\n      ) => {\\n        translateOption.y = \\"100%\\";\\n      }\\n    );\\n    enterHandle.finish(\\n      (\\n        translateOption: TranslateOption,\\n        scaleOption: ScaleOption,\\n        opacityOption: OpacityOption\\n      ) => {\\n        translateOption.y = \\"0\\";\\n      }\\n    );\\n    enterHandle.duration = 500;\\n\\n    // 出场动画\\n    exitHandle.start(\\n      (\\n        translateOption: TranslateOption,\\n        scaleOption: ScaleOption,\\n        opacityOption: OpacityOption\\n      ) => {\\n        translateOption.y = \\"0\\";\\n      }\\n    );\\n    exitHandle.finish(\\n      (\\n        translateOption: TranslateOption,\\n        scaleOption: ScaleOption,\\n        opacityOption: OpacityOption\\n      ) => {\\n        translateOption.y = \\"100%\\";\\n      }\\n    );\\n    exitHandle.duration = 500;\\n  }\\n}\\n```\\n\\n### 使用动画\\n\\n在 HMRouter 上使用\\n\\n```javascript\\n@HMRouter({\\n  pageUrl: \'CartDetail\',\\n  // 2 使用动画\\n  animator: \\"liveCommentsAnimator\\"\\n})\\n@Component\\nexport struct CartDetail {\\n  build() {\\n    Column() {\\n      Button(\'我的是购物车详情页面\')\\n    }\\n    .width(\\"100%\\")\\n    .height(\\"100%\\")\\n    .justifyContent(FlexAlign.Center)\\n  }\\n}\\n```\\n\\n### 效果\\n\\n![PixPin_2024-12-24_11-22-25](%E5%B0%8F%E7%99%BD%E5%BF%85%E7%9C%8B%20HarmonyOS%20Next%20HMRouter%20%E8%BD%BB%E6%9D%BE%E4%B8%8A%E6%89%8B%E7%A7%98%E7%B1%8D.assets/PixPin_2024-12-24_11-22-25.gif)\\n\\n## 拦截器\\n\\n拦截器可以分成 2 种，局部拦截器和全局拦截器\\n\\n标记在实现了`IHMInterceptor`的对象上，声明此对象为一个拦截器\\n\\n- interceptorName: string, 拦截器名称，必填\\n- priority: number, 拦截器优先级，数字越大优先级越高，非必填，默认为 9；\\n- global: boolean, 是否为全局拦截器，当配置为 true 时，所有跳转均过此拦截器；默认为 false，当为 false 时需要配置在@HMRouter 的 interceptors 中才生效。\\n\\n**执行时机：**\\n\\n在路由栈发生变化前，转场动画发生前进行回调。 1.当发生 push/replace 路由时，pageUrl 为空时，拦截器不会执行，需传入 pageUrl 路径；\\n\\n2.当跳转 pageUrl 目标页面不存在时，执行全局以及发起页面拦截器，当拦截器未执行 DO_REJECT 时，然后执行路由的 onLost 回调\\n\\n3.当跳转 pageUrl 目标页面存在时，执行全局，发起页面和目标页面的拦截器；\\n\\n**拦截器执行顺序：**\\n\\n1. 按照优先级顺序执行，不区分自定义或者全局拦截器，优先级相同时先执行@HMRouter 中定义的自定义拦截器\\n2. 当优先级一致时，先执行 srcPage>targetPage>global\\n\\n> srcPage 表示跳转发起页面。\\n>\\n> targetPage 表示跳转结束时展示的页面。\\n\\n### 局部拦截器\\n\\n局部拦截器只对单个页面生效。我们拿 登录页面来测试 从首页 跳转到登录页面，登录页面的拦截器便会触发\\n\\n> entry/src/main/ets/views/LoginPage.ets\\n\\n**定义拦截器**\\n\\n```javascript\\n@HMInterceptor({ interceptorName: \\"Loginterceptor\\", global: false })\\nexport class JumpInfoInterceptor implements IHMInterceptor {\\n  handle(info: HMInterceptorInfo): HMInterceptorAction {\\n    console.log(\\"拦截器\\", JSON.stringify(info));\\n    // DO_NEXT  正常跳转\\n    // DO_REJECT 拒绝跳转\\n    return HMInterceptorAction.DO_NEXT;\\n  }\\n}\\n```\\n\\n**使用拦截器**\\n\\n```typescript\\n// 使用拦截器\\n@HMRouter({\\n  pageUrl: \'LoginPage\',\\n  interceptors: [\'Loginterceptor\']\\n})\\n@Component\\nexport struct LoginPage {\\n  build() {\\n    Column() {\\n      Button(\'登录页面\')\\n    }\\n    .width(\\"100%\\")\\n    .height(\\"100%\\")\\n    .justifyContent(FlexAlign.Center)\\n  }\\n}\\n```\\n\\n**输出效果**\\n\\n```json\\n{\\n  \\"srcName\\": \\"HM_NavBar\\",\\n  \\"targetName\\": \\"LoginPage\\",\\n  \\"type\\": \\"push\\",\\n  \\"routerPathInfo\\": {\\n    \\"pageUrl\\": \\"LoginPage\\"\\n  },\\n  \\"context\\": {\\n    \\"instanceId_\\": 100000\\n  },\\n  \\"isSrc\\": false\\n}\\n```\\n\\n### 全局拦截器\\n\\n直接在 index 页面上使用\\n\\n```javascript\\n  aboutToAppear(): void {\\n    // 注册全局拦截器\\n    HMRouterMgr.registerGlobalInterceptor({\\n      interceptorName: \\"拦截器的名字\\",\\n      // 优先级\\n      priority: 1,\\n      // 拦截器\\n      interceptor: {\\n        // 处理函数\\n        handle(info: HMInterceptorInfo) {\\n          return HMInterceptorAction.DO_NEXT\\n        }\\n      }\\n    })\\n  }\\n```\\n\\n## 生命周期\\n\\n```\\n@HMLifecycle(lifecycleName, priority, global)\\n```\\n\\n标记在实现了 IHMLifecycle 的对象上，声明此对象为一个自定义生命周期处理器\\n\\n- lifecycleName: string, 自定义生命周期处理器名称，必填\\n- priority: number, 生命周期优先级，数字越大优先级越高，非必填，默认为 9；\\n- global: boolean, 是否为全局生命周期，当配置为 true 时，所有页面生命周期事件会转发到此对象；默认为 false\\n\\n**生命周期触发顺序：**\\n\\n按照优先级顺序触发，不区分自定义或者全局生命周期，优先级相同时先执行@HMRouter 中定义的自定义生命周期\\n\\n我们可以继续在登录页面上测试对应的生命周期\\n\\n> entry/src/main/ets/views/LoginPage.ets\\n\\n### 定义生命周期\\n\\n```javascript\\n@HMLifecycle({ lifecycleName: \'LoginLifecycle\' })\\nexport class PageDurationLifecycle implements IHMLifecycle {\\n  private time: number = 0;\\n\\n  onShown(ctx: HMLifecycleContext): void {\\n    this.time = new Date().getTime();\\n    console.log(\\"生命周期\\", JSON.stringify(ctx))\\n  }\\n\\n  onHidden(ctx: HMLifecycleContext): void {\\n    const duration = new Date().getTime() - this.time;\\n  }\\n}\\n```\\n\\n### 使用生命周期\\n\\n```javascript\\n\\n// 使用拦截器\\n@HMRouter({\\n  pageUrl: \'LoginPage\',\\n  interceptors: [\'Loginterceptor\'],\\n  lifecycle: \\"LoginLifecycle\\"\\n})\\n@Component\\nexport struct LoginPage {\\n  build() {\\n    Column() {\\n      Button(\'登录页面\')\\n    }\\n    .width(\\"100%\\")\\n    .height(\\"100%\\")\\n    .justifyContent(FlexAlign.Center)\\n  }\\n}\\n```\\n\\n### 完整生命周期\\n\\n```javascript\\nexport interface HMLifecycleContext {\\n    uiContext: UIContext;\\n    navContext?: NavDestinationContext;\\n}\\nexport type HMLifecycleCallback = (ctx: HMLifecycleContext) => boolean | void;\\nexport interface IHMLifecycle {\\n    onPrepare?(ctx: HMLifecycleContext): void;\\n    onAppear?(ctx: HMLifecycleContext): void;\\n    onDisAppear?(ctx: HMLifecycleContext): void;\\n    onShown?(ctx: HMLifecycleContext): void;\\n    onHidden?(ctx: HMLifecycleContext): void;\\n    onWillAppear?(ctx: HMLifecycleContext): void;\\n    onWillDisappear?(ctx: HMLifecycleContext): void;\\n    onWillShow?(ctx: HMLifecycleContext): void;\\n    onWillHide?(ctx: HMLifecycleContext): void;\\n    onReady?(ctx: HMLifecycleContext): void;\\n    onBackPressed?(ctx: HMLifecycleContext): boolean;\\n}\\n\\n```\\n\\n\\n\\n### 页面组件和生命周期数据交互\\n\\n生命周期实例中可以初始化对象，并且在UI组件中获取做为状态变量\\n\\n```javascript\\nimport {\\n  HMInterceptor,\\n  HMInterceptorAction,\\n  HMInterceptorInfo,\\n  HMLifecycle,\\n  HMLifecycleContext,\\n  HMRouter,\\n  HMRouterMgr,\\n  IHMInterceptor,\\n  IHMLifecycle\\n} from \'@hadss/hmrouter\';\\n\\n// 定义拦截器\\n@HMInterceptor({ interceptorName: \'Loginterceptor\', global: false })\\nexport class JumpInfoInterceptor implements IHMInterceptor {\\n  handle(info: HMInterceptorInfo): HMInterceptorAction {\\n    console.log(\\"拦截器\\", JSON.stringify(info))\\n    return HMInterceptorAction.DO_NEXT;\\n  }\\n}\\n\\n@Observed\\nexport class ObservedModel {\\n  isLoad: boolean = false;\\n}\\n\\n@HMLifecycle({ lifecycleName: \'LoginLifecycle\' })\\nexport class PageDurationLifecycle implements IHMLifecycle {\\n  model: ObservedModel = new ObservedModel()\\n\\n  onAppear(ctx: HMLifecycleContext): void {\\n  }\\n}\\n\\n\\n// 使用拦截器\\n@HMRouter({\\n  pageUrl: \'LoginPage\',\\n  interceptors: [\'Loginterceptor\'],\\n  lifecycle: \\"LoginLifecycle\\"\\n})\\n@Component\\nexport struct LoginPage {\\n  @State model: ObservedModel | null =\\n    (HMRouterMgr.getCurrentLifecycleOwner()?.getLifecycle() as PageDurationLifecycle).model;\\n\\n  build() {\\n    Column() {\\n      Button(\'登录页面\' + this.model?.isLoad)\\n        .onClick(() => {\\n          this.model!.isLoad = !this.model?.isLoad\\n        })\\n\\n    }\\n    .width(\\"100%\\")\\n    .height(\\"100%\\")\\n    .justifyContent(FlexAlign.Center)\\n  }\\n}\\n```\\n\\n## 小结\\n\\nhmrouter 的官网文档还是挺零散的，需要结合文档配套学习使用\\n\\n### HMRouter 接口和属性列表\\n\\n[查看详情](https://gitee.com/hadss/hmrouter/blob/dev/docs/Reference.md)\\n\\n### HMRouterPlugin 编译插件使用说明\\n\\n[查看详情](https://gitee.com/hadss/hmrouter/blob/dev/HMRouterPlugin/README.md)\\n\\n### HMRouterTransitions 高阶转场动画使用说明\\n\\n[查看详情](https://gitee.com/hadss/hmrouter/blob/dev/HMRouterTransitions/README.md)\\n\\n### 自定义模板使用说明\\n\\n[查看详情](https://gitee.com/hadss/hmrouter/blob/dev/docs/CustomTemplate.md)\\n\\n### 自定义转场动画使用说明\\n\\n[查看详情](https://gitee.com/hadss/hmrouter/blob/dev/docs/CustomTransition.md)\\n\\n### 更多常见解决方案\\n\\n[查看详情](https://gitee.com/hadss/hmrouter/blob/dev/docs/Scene.md)\\n\\n### SampleCode\\n\\n[查看详情](https://gitee.com/harmonyos_samples/HMRouter)\\n\\n### 更多示例\\n\\n[查看详情](https://gitee.com/hadss/hmrouter/tree/dev/HMRouterExamples)\\n\\n### FAQ\\n\\n[查看详情](https://gitee.com/hadss/hmrouter/blob/dev/docs/FAQ.md)\\n\\n### 原理介绍\\n\\n[查看详情](https://gitee.com/link?target=https%3A%2F%2Fdeveloper.huawei.com%2Fconsumer%2Fcn%2Fforum%2Ftopic%2F0207153170697988820%3Ffid%3D0109140870620153026)"}'),r={name:"鸿蒙开发技巧/小白必看 HarmonyOS Next HMRouter 轻松上手秘籍/小白必看 HarmonyOS Next HMRouter 轻松上手秘籍.md"};function k(E,s,d,o,c,g){return a(),n("div",null,[...s[0]||(s[0]=[t("",141)])])}const b=i(r,[["render",k]]);export{u as __pageData,b as default};
